using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class C1Before{[Serializable]class Row{public string name,status,detail;}[Serializable]class Report{public Row[] rows;}public static void Run(){var rows=new[]{new Row{name="camp-ruins-entry",status=typeof(AdventureFlow).GetMethod("DepartRuins")!=null?"PASS":"FAIL",detail="No existing C1 expedition entry"},new Row{name="dedicated-map-schema",status=typeof(ForestLayout).GetField("mapId")!=null?"PASS":"FAIL",detail="Only forest revisions1..5"},new Row{name="ruins-runtime",status=typeof(CombatSession).Assembly.GetType("RuinsExploration")!=null?"PASS":"FAIL",detail="No persistent ruins mechanisms"}};string root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);File.WriteAllText(root+"/before.json",JsonUtility.ToJson(new Report{rows=rows},true));EditorApplication.Exit(rows.Any(x=>x.status=="FAIL")?1:0);}}